		Memo("帮书生对下联。");
		Assign($SubEvent20, 2);
		Goto @end;
	@Sub2002:
		Say("书生：公子，可有对出下联？", 94);
		Say("杨影枫：我还在想。", 2);
		Say("书生：我觉得应该可以用上这里的蝴蝶，可还是怎么也想不出来。", 94);
		Goto @end;
	@Sub2005:
		Say("杨影枫：兄台，在下偶得一句下联，不知合不合适，兄台听听。", 2);
		Say("杨影枫：你的上联是：<enter>一群游鱼逐波去。", 2);
		Say("杨影枫：我的下联是：", 2);
		Select(85030, 85040, 85050 , $DuiLian);
		If ($DuiLian == 0) @DuiLian0;
		If ($DuiLian == 1) @DuiLian1;
		@DuiLian0:
